    async void GenerateChunkAsync(Vector2Int chunkPos)
    {
        TerrainChunk chunk = await Task.Run(() => vistaApi.GenerateTerrainChunk(chunkPos, CalculateLodLevel(chunkPos)));
        chunkMap.TryAdd(chunkPos, chunk);
    }

    int CalculateLodLevel(Vector2Int chunkPos)
    {
        Vector2Int playerPos = new Vector2Int(Mathf.RoundToInt(player.position.x / 100f), Mathf.RoundToInt(player.position.z / 100f));
        int distanceFromPlayer = Mathf.Max(Mathf.Abs(chunkPos.x - playerPos.x), Mathf.Abs(chunkPos.y - playerPos.y));
        return Mathf.Min(3, Mathf.Max(0, Mathf.FloorToInt(distanceFromPlayer / renderDistance * 3)));
    }

    void UnloadChunk(Vector2Int chunkPos)
    {
        if (chunkMap.TryGetValue(chunkPos, out TerrainChunk chunk))
        {
            Destroy(chunk.gameObject);
            chunkMap.TryRemove(chunkPos, out _);
        }
    }

    bool IsOutsideRenderDistance(Vector2Int chunkPos, Vector2Int playerPos)
    {
        return Mathf.Abs(chunkPos.x - playerPos.x) > renderDistance || Mathf.Abs(chunkPos.y - playerPos.y) > renderDistance;
    }
